// =====================================================================
// UBAH KONFIGURASI DI BLOK INI.
// =====================================================================
const cfg = {
  baseUrl: 'https://GANTI-DENGAN-DOMAIN-LM-APP',
  evoInstance: 'notif-outlet',
};
if (cfg.baseUrl.includes('GANTI')) {
  throw new Error('Isi baseUrl di node "1. Baca Balasan" dengan domain LM App Anda.');
}
cfg.baseUrl = cfg.baseUrl.replace(/\/+$/, '');

// ---------------------------------------------------------------------
// Baca balasan WhatsApp dari Evolution API.
//
// Formatnya HARUS persis "SETUJU <kode>" atau "TOLAK <kode>". Kalimat bebas
// sengaja tidak ditebak-tebak: "jangan disetujui dulu" mengandung kata
// "setuju", dan membacanya sebagai persetujuan berarti uang keluar atas
// kalimat yang artinya justru sebaliknya. Yang tidak cocok diabaikan diam-diam
// supaya percakapan biasa di nomor yang sama tidak ikut terproses.
// ---------------------------------------------------------------------
const out = [];

for (const item of $input.all()) {
  const root = item.json || {};
  const body = root.body || root;
  const data = body.data || {};
  const key = data.key || {};

  if (key.fromMe) continue;                                   // pesan kita sendiri

  const jid = String(key.remoteJid || '');
  if (!jid || jid.endsWith('@g.us')) continue;                // grup, bukan japri

  const msg = data.message || {};
  const text = String(
    msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || ''
  ).trim();

  const m = text.match(/^(setuju|approve|tolak|reject)\s+([A-Za-z0-9_-]{16,})$/i);
  if (!m) continue;

  out.push({
    json: {
      ...cfg,
      phone: jid.split('@')[0],
      token: m[2],
      decision: /^(setuju|approve)$/i.test(m[1]) ? 'approve' : 'reject',
    },
  });
}

console.log(`[LM] balasan approval terbaca: ${out.length}`);
return out;

// Kabari approver hasilnya. Diam setelah dia membalas adalah cara tercepat
// membuat orang mengira approval-nya gagal lalu mengulanginya.
const sumber = $('1. Baca Balasan').all();
const masuk = $input.all();
const out = [];

for (let i = 0; i < masuk.length; i++) {
  const res = masuk[i].json || {};
  const src = (sumber[i] || sumber[0]).json;
  const status = res.statusCode;
  const body = res.body || {};

  let text;
  if (status === 200 && body.ok) {
    text = body.decision === 'approve'
      ? [
          '✅ Pengajuan *DISETUJUI*.',
          '',
          'Diteruskan ke Admin Operasional untuk verifikasi.',
          'Pembayaran tetap dilakukan Owner di dalam aplikasi.',
        ].join('\n')
      : '🚫 Pengajuan *DITOLAK*.';
  } else {
    // Sebutkan alasan apa adanya: "kode kedaluwarsa" dan "sudah dipakai"
    // menuntut tindakan yang berbeda dari si approver.
    text = [
      `⚠️ Tidak bisa diproses: ${body.error || 'HTTP ' + status}`,
      '',
      'Kode hanya berlaku 60 menit dan sekali pakai.',
      'Selesaikan lewat aplikasi bila perlu.',
    ].join('\n');
  }

  out.push({ json: { number: src.phone, text } });
}

return out;
